import Foundation

/// What the service answered: the status, and the body when it is JSON.
public struct Answer: Sendable {
    public var status: Int
    public var body: JSON?

    public var ok: Bool { (200..<300).contains(status) }
}

/// Where the screens call the service, and how: every request as JSON,
/// with the shared cookie storage, so a session the service opens with a
/// cookie holds across calls, as a browser's does.
public enum Service {
    /// Where the service answers; the app sets it at launch.
    @MainActor public static var baseURL = URL(string: "http://localhost:8080")!

    /// Sends a request and reads its answer. A path's {parameter} is filled
    /// from parameters, each value as one segment.
    @MainActor
    public static func send(_ method: String, _ path: String, parameters: [String: String] = [:], query: [URLQueryItem] = [], body: JSON? = nil, headers: [String: String] = [:]) async throws -> Answer {
        var filled = path
        for (name, value) in parameters {
            filled = filled.replacingOccurrences(of: "{\(name)}", with: segment(value))
        }
        guard var components = URLComponents(url: baseURL.appending(path: filled, directoryHint: .notDirectory), resolvingAgainstBaseURL: false) else {
            throw URLError(.badURL)
        }
        if !query.isEmpty {
            components.queryItems = query
        }
        guard let url = components.url else {
            throw URLError(.badURL)
        }
        var request = URLRequest(url: url)
        request.httpMethod = method
        request.setValue("application/json, application/problem+json", forHTTPHeaderField: "Accept")
        for (name, value) in headers {
            request.setValue(value, forHTTPHeaderField: name)
        }
        if let body {
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.httpBody = body.data
        }
        let (data, response) = try await URLSession.shared.data(for: request)
        let status = (response as? HTTPURLResponse)?.statusCode ?? 0
        return Answer(status: status, body: data.isEmpty ? nil : JSON.parse(data))
    }

    /// A value as one path segment; "." and ".." would otherwise move up the path.
    public static func segment(_ value: String) -> String {
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_~"))
        let encoded = value.addingPercentEncoding(withAllowedCharacters: allowed) ?? value
        return encoded == "." || encoded == ".." ? encoded.replacingOccurrences(of: ".", with: "%2E") : encoded
    }
}
